def main():
    print(f"UHS MBBS Topics Count: {len(UHS_MBBS_TOPICS)}")
    print(f"PLAB / UKMLA Topics Count: {len(PLAB_UKMLA_TOPICS)}")
    print(f"AMC Topics Count: {len(AMC_TOPICS)}")

    assert len(UHS_MBBS_TOPICS) == 100, f"Expected 100 UHS topics, got {len(UHS_MBBS_TOPICS)}"
    assert len(PLAB_UKMLA_TOPICS) == 100, f"Expected 100 PLAB topics, got {len(PLAB_UKMLA_TOPICS)}"
    assert len(AMC_TOPICS) == 100, f"Expected 100 AMC topics, got {len(AMC_TOPICS)}"

    for i, t in enumerate(UHS_MBBS_TOPICS):
        assert t[1] in TAXONOMY_SUBJECTS, f"Invalid subject {t[1]} at UHS #{i}: {t[0]}"
        assert t[2] in TAXONOMY_SYSTEMS, f"Invalid system {t[2]} at UHS #{i}: {t[0]}"
        assert t[5].startswith("https://"), f"Invalid URL at UHS #{i}: {t[5]}"

    for i, t in enumerate(PLAB_UKMLA_TOPICS):
        assert t[1] in TAXONOMY_SUBJECTS, f"Invalid subject {t[1]} at PLAB #{i}: {t[0]}"
        assert t[2] in TAXONOMY_SYSTEMS, f"Invalid system {t[2]} at PLAB #{i}: {t[0]}"
        assert t[5].startswith("https://"), f"Invalid URL at PLAB #{i}: {t[5]}"

    for i, t in enumerate(AMC_TOPICS):
        assert t[1] in TAXONOMY_SUBJECTS, f"Invalid subject {t[1]} at AMC #{i}: {t[0]}"
        assert t[2] in TAXONOMY_SYSTEMS, f"Invalid system {t[2]} at AMC #{i}: {t[0]}"
        assert t[5].startswith("https://"), f"Invalid URL at AMC #{i}: {t[5]}"

    out_path = os.path.join(os.path.dirname(__file__), "mega94_topics_b.py")
    with open(out_path, "w", encoding="utf-8") as f:
        f.write("# Auto-generated Mega-Batch 94 Part B topics (UHS 100, PLAB 100, AMC 100)\n\n")
        f.write(f"UHS_MBBS_TOPICS = {json.dumps(UHS_MBBS_TOPICS, indent=2)}\n\n")
        f.write(f"PLAB_UKMLA_TOPICS = {json.dumps(PLAB_UKMLA_TOPICS, indent=2)}\n\n")
        f.write(f"AMC_TOPICS = {json.dumps(AMC_TOPICS, indent=2)}\n")

    print(f"Saved Part B topics to {out_path}!")

if __name__ == "__main__":
    main()
